// Lista real de id_eap, consultada ao vivo no Supabase em 2026-09-18
// (`SELECT DISTINCT id_eap, id_obra FROM EAP`, paginado -- 7093 linhas,
// 15 grupos). NÃO é 1 por obra: obra 107 (NN-AP) tem 6 grupos, obra 94
// (Porto Itapoá) tem 2. `id_eap=66` (obra 103, CNPEM-Auditório) fica de
// fora de propósito -- mesma exclusão já usada em RMI/Mapa de Compras/OC
// (obra 103 não está no array OBRAS do painel). Mesma lista do fluxo
// 'EAP (Avanço Físico)' -- manter as 2 sincronizadas se mudar.
const ID_EAP = [
  { id_eap: 32,  id_obra: 94,  nome_obra: 'Porto Itapoá' },
  { id_eap: 121, id_obra: 94,  nome_obra: 'Porto Itapoá' },
  { id_eap: 51,  id_obra: 91,  nome_obra: 'Novo Nordisk - UB/SP' },
  { id_eap: 73,  id_obra: 106, nome_obra: 'CNPEM - Faseado' },
  { id_eap: 86,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 87,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 88,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 89,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 90,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 94,  id_obra: 107, nome_obra: 'Novo Nordisk - AP' },
  { id_eap: 110, id_obra: 108, nome_obra: 'Novo Nordisk - AP - Reforço' },
  { id_eap: 114, id_obra: 110, nome_obra: 'Hitachi' },
  { id_eap: 115, id_obra: 110, nome_obra: 'Hitachi' },
  { id_eap: 127, id_obra: 114, nome_obra: 'IPEN' },
  // { id_eap: 66, id_obra: 103, nome_obra: 'CNPEM - Auditório' }, -- fora do painel
];

return ID_EAP.map(o => ({ json: o }));

// Iteração por TAREFA x DATA (pedido explícito, 2026-09-18: não só
// 'hoje' -- também recobre o dia anterior). Janela FIXA de 2 dias (hoje +
// ontem) -- não é a janela de 21 dias usada em outros pontos do painel
// (aderência/TV), decisão explícita de manter enxuto aqui.
//
// Envelope CONFIRMADO contra resposta real (2026-09-18): {data: {id_eap,
// nome_eap, id_obra, nome_obra, tarefas: [...]}} -- 'data' é OBJETO, não
// array. Node anterior está em Response Format = Text -- parse manual,
// com o texto cru exposto no erro se falhar.
const DIAS_JANELA = 2;
const idEapLoop = $('Loop id_eap (1 por vez)').item.json.id_eap;

const bruto = typeof $json === 'string' ? $json : ($json.data !== undefined ? $json.data : $json.body ?? JSON.stringify($json));
let corpo;
try {
  corpo = typeof bruto === 'string' ? JSON.parse(bruto) : bruto;
} catch (e) {
  throw new Error(`id_eap ${idEapLoop}: resposta de tarefas nao e JSON valido. Texto cru (ate 1000 chars): ` + String(bruto).slice(0, 1000));
}

const grupo = corpo?.data;
if (!grupo || !Array.isArray(grupo.tarefas)) {
  throw new Error(`id_eap ${idEapLoop}: envelope inesperado de tarefas: ` + JSON.stringify(corpo).slice(0, 300));
}
const idObra = Number(grupo.id_obra);
const idEap = Number(grupo.id_eap ?? idEapLoop);
const itens = grupo.tarefas;

const datas = [];
for (let i = 0; i < DIAS_JANELA; i++) {
  const d = new Date();
  d.setDate(d.getDate() - i);
  datas.push(d.toISOString().slice(0, 10)); // YYYY-MM-DD
}

const combinacoes = [];
for (const t of itens) {
  for (const data of datas) {
    combinacoes.push({ json: { card_id: Number(t.id), id_obra: idObra, id_eap: idEap, data } });
  }
}
return combinacoes;

// TODO: mapeamento de campos AINDA NÃO CONFIRMADO -- escrito às cegas,
// sem ter visto uma resposta real do endpoint 'avancos'. Ajustar os
// nomes à ESQUERDA (fonte.<campo>) assim que tivermos uma amostra real;
// os nomes à DIREITA já são as colunas reais de
// `eap_apontamentos`/`eap_tarefas` no MySQL (migration 008_eap.sql).
//
// Assumindo que a resposta é 1 objeto (não lista), já que a URL pede um
// card_id + data específicos. Se vier vazio/null, é dia sem apontamento
// -- pula sem gravar nada (não é erro), devolvendo lista vazia.

const fonte = $json;
if (!fonte || (Array.isArray(fonte) && !fonte.length)) return [];
const a = Array.isArray(fonte) ? fonte[0] : fonte;

const combinacao = $('Loop tarefa+data (1 por vez)').item.json;

const item = {
  tarefa_id: combinacao.card_id,
  id_eap_grupo: combinacao.id_eap,
  nome_eap: a.nome_eap,
  nome_obra: a.nome_obra,
  data_do_input: combinacao.data,
  edt: a.edt,
  tarefa: a.tarefa,
  qtd: a.qtd,
  unidade: a.unidade,
  avanco_atual: a.avanco_atual,
  avanco_atual_p100: a.avanco_atual_p100,
  avanco_diario: a.avanco_diario,
  usuario_avanco_diario: a.usuario_avanco_diario,
  uuid_origem: a.uuid || a.UUID,
  meta_diaria: a.meta_diaria,
  status_qualidade: a.status_qualidade,
  desvio: a.desvio,
  hht_consumido: a.hht_consumido,
};

return [{ json: { item } }];

const escapar = (v) => "'" + String(v).replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'";
const valorSql = (v) => {
  if (v === null || v === undefined || v === '') return 'NULL';
  if (typeof v === 'string' && v.startsWith('0000')) return 'NULL'; // data placeholder tipo 0000-00-00, mesmo tratamento ja usado no prototipo/index.html
  if (typeof v === 'number') return Number.isFinite(v) ? String(v) : 'NULL';
  return escapar(v);
};

const item = $json.item;

const COLUNAS_APONTAMENTO = [
  'tarefa_id', 'id_eap_grupo', 'nome_eap', 'nome_obra', 'data_do_input', 'edt',
  'tarefa', 'qtd', 'unidade', 'avanco_atual', 'avanco_atual_p100', 'avanco_diario',
  'usuario_avanco_diario', 'uuid_origem', 'meta_diaria', 'status_qualidade',
];
const colunasSql = COLUNAS_APONTAMENTO.map(c => `\`${c}\``).join(',');
const valoresSql = COLUNAS_APONTAMENTO.map(c => valorSql(item[c])).join(',');
const atualizaApontamento = COLUNAS_APONTAMENTO
  .filter(c => c !== 'tarefa_id' && c !== 'data_do_input')
  .map(c => `\`${c}\` = VALUES(\`${c}\`)`).join(', ');
const sqlApontamento = `INSERT INTO eap_apontamentos (${colunasSql}) VALUES (${valoresSql}) ON DUPLICATE KEY UPDATE ${atualizaApontamento}`;

const COLUNAS_SNAPSHOT = ['avanco_atual', 'desvio', 'meta_diaria', 'avanco_diario', 'status_qualidade', 'hht_consumido'];
const setSnapshot = COLUNAS_SNAPSHOT.map(c => `\`${c}\` = ${valorSql(item[c])}`).join(', ');
const sqlSnapshot = `UPDATE eap_tarefas SET ${setSnapshot} WHERE id = ${valorSql(item.tarefa_id)}`;

return [{ json: { sqlApontamento, sqlSnapshot } }];
